// first animation frame, grey plant textures tinted like Minecraft does). Made before 02_world.js builds TILE_UV.
const MC_NEW_TILES = {"mc_acacia_hanging_sign":"","mc_acacia_sign":"","mc_anvil":"","mc_azalea_plant":"","mc_azalea_side":"","mc_azalea_top":"","mc_bamboo_hanging_sign":"","mc_bamboo_large_leaves":"","mc_bamboo_sign":"","mc_bamboo_singleleaf":"","mc_big_dripleaf_side":"","mc_big_dripleaf_tip":"","mc_birch_hanging_sign":"","mc_birch_sign":"","mc_brewing_stand":"","mc_brewing_stand_base":"","mc_calibrated_sculk_sensor_amethyst":"","mc_calibrated_sculk_sensor_input_side":"","mc_cauldron_bottom":"","mc_cauldron_inner":"","mc_cauldron_top":"","mc_cherry_hanging_sign":"","mc_cherry_sign":"","mc_chipped_anvil_top":"","mc_cocoa_stage0":"","mc_cocoa_stage1":"","mc_cocoa_stage2":"","mc_crimson_hanging_sign":"","mc_crimson_sign":"","mc_damaged_anvil_top":"","mc_dark_oak_hanging_sign":"","mc_dark_oak_log":"","mc_dark_oak_sign":"","mc_dried_ghast_hydration_0_bottom":"","mc_dried_ghast_hydration_0_east":"","mc_dried_ghast_hydration_0_north":"","mc_dried_ghast_hydration_0_south":"","mc_dried_ghast_hydration_0_tentacles":"","mc_dried_ghast_hydration_0_top":"","mc_dried_ghast_hydration_0_west":"","mc_fern":"","mc_flowering_azalea_side":"","mc_flowering_azalea_top":"","mc_grindstone_pivot":"","mc_grindstone_round":"","mc_grindstone_side":"","mc_hopper_outside":"","mc_iron_chain":"","mc_jungle_hanging_sign":"","mc_jungle_sign":"","mc_lantern":"","mc_leaf_litter":"","mc_lectern_base":"","mc_lectern_front":"","mc_lectern_sides":"","mc_mangrove_hanging_sign":"","mc_mangrove_sign":"","mc_oak_hanging_sign":"","mc_oak_sign":"","mc_pale_moss_carpet":"","mc_pale_oak_hanging_sign":"","mc_pale_oak_sign":"","mc_pink_petals_stem":"","mc_poplar_hanging_sign":"","mc_poplar_sign":"","mc_scaffolding_bottom":"","mc_sculk_sensor_bottom":"","mc_sculk_sensor_side":"","mc_sculk_sensor_tendril_active":"","mc_shelf_mushroom_stage1":"","mc_sniffer_egg_not_cracked_bottom":"","mc_sniffer_egg_not_cracked_east":"","mc_sniffer_egg_not_cracked_north":"","mc_sniffer_egg_not_cracked_south":"","mc_sniffer_egg_not_cracked_top":"","mc_sniffer_egg_not_cracked_west":"","mc_soul_lantern":"","mc_spruce_hanging_sign":"","mc_spruce_sign":"","mc_stonecutter_bottom":"","mc_stonecutter_saw":"","mc_straw_bed":"","mc_tripwire_hook":"","mc_warped_hanging_sign":"","mc_warped_sign":"","mc_wildflowers_stem":""};
for (const n in MC_NEW_TILES) { if (TILE[n] !== undefined) continue; const px = Uint8ClampedArray.from(atob(MC_NEW_TILES[n]), ch => ch.charCodeAt(0));
  makeTile(n, (set) => { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const i = (y * 16 + x) * 4; if (px[i + 3]) set(x, y, [px[i], px[i + 1], px[i + 2]], px[i + 3]); } }); }
